const $=s=>document.querySelector(s);let players=[];async function api(action,data){const r=await fetch('/.netlify/functions/api?action='+action,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||'Request failed');return x}function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function render(){const q=$('#searchPlayers').value.toLowerCase();const shown=players.filter(p=>[p.username,p.first_name,p.last_name,p.phone,p.city,p.state,p.zip_code].join(' ').toLowerCase().includes(q));$('#playerRows').innerHTML=shown.map(p=>`<tr><td data-label="Status"><span class="presence ${p.online?'online':''}"></span>${p.online?'Online':'Offline'}</td><td><strong>${safe(p.first_name)} ${safe(p.last_name)}</strong><small>@${safe(p.username)}</small></td><td>${safe(p.phone)}</td><td>${safe(p.street_address)}<br>${safe(p.city)}, ${safe(p.state)} ${safe(p.zip_code)}</td><td>${safe(p.age)}</td><td>${p.games.played} played<br>${p.games.wins} won</td><td>${new Date(p.created_at).toLocaleDateString()}</td></tr>`).join('')||'<tr><td colspan="7">No matching players.</td></tr>'}async function load(){try{const d=await api('admin-data');players=d.players;$('#registered').textContent=d.summary.registered;$('#activeToday').textContent=d.summary.activeToday;$('#online').textContent=d.summary.online;$('#games').textContent=d.summary.games;$('#adminLogin').hidden=true;$('#dashboard').hidden=false;render()}catch(e){$('#dashboard').hidden=true;$('#adminLogin').hidden=false}}$('#adminLoginForm').onsubmit=async e=>{e.preventDefault();$('#loginMessage').textContent='Checking…';try{await api('admin-login',{password:$('#adminPassword').value});$('#adminPassword').value='';$('#loginMessage').textContent='';await load()}catch(e){$('#loginMessage').textContent=e.message}};$('#searchPlayers').oninput=render;$('#refreshData').onclick=load;$('#adminLogout').onclick=async()=>{await api('admin-logout',{});location.reload()};load();